/* Runvis homepage translations — English. One language per file so a
   visitor downloads 1/6 of the dictionary, not all of it. i18n.js
   injects exactly the file it needs and calls RunvisOnDict when it lands. */
(window.RUNVIS_I18N=window.RUNVIS_I18N||{})["en"]={"a11y.langmenu": "Display language", "a11y.langname": "English", "a11y.playing": "Playing sample voice", "a11y.skip": "Skip to main content", "a11y.stopped": "Playback stopped", "a11y.wspause": "Stop auto-advance", "a11y.wsplay": "Start auto-advance", "alt.phone.detail": "iPhone metric detail — the 7-day training-load (CTL) trend, my 28-day range and what the metric means", "alt.phone.glance": "iPhone body & running report — Training load flow, Training Load, Lactate Threshold (est.), Endurance training volume and Hill exposure tiles", "alt.phone.hero": "iPhone home — today’s call is rest (full rest or an easy walk)", "alt.phone.plan": "iPhone weekly training plan screen", "alt.phone.race": "iPhone race prediction screen", "alt.watch.decision": "Apple Watch Ultra — Runvis today’s call: readiness ring and a rest day", "alt.watch.evidence": "Apple Watch Ultra — Runvis today’s evidence: sleep and HRV", "alt.watch.map": "Apple Watch Ultra — Runvis live GPS map mid-run with distance, time and pace", "alt.watch.pace": "Apple Watch Ultra — Runvis mid-run pace with average, speed, GAP and grade", "alt.watch.start": "Apple Watch Ultra — Runvis workout picker: running and indoor running", "alt.watch.zone": "Apple Watch Ultra — Runvis heart-rate zone arc", "cs.marketing": "(Optional) I agree to receive launch news and product updates.", "cs.purpose": ": sending your TestFlight beta invite", "cs.retain": ": deleted without delay once its purpose is fulfilled (the beta invitation has been sent), and in any case within one year of collection", "form.busy": "Sign-ups aren’t open just yet — hang tight!", "form.fail": "That didn’t go through. Please try again in a moment.", "form.mailto": "Sign up by email: help@runvis.app", "form.neterr": "Network error. Please try again in a moment.", "form.novoice": "This browser does not support voice playback.", "form.ok": "You’re registered. We’ll write to this address the day the opening date is set, and when the beta opens one invite goes out in signup order. No confirmation email is sent, so take one look at the address shown above and check it is right. Ask us at help@runvis.app any time and we’ll delete it. While you wait, run the 5K demo. 🏃", "form.okcta": "Run the 5K demo", "form.sending": "Sending…", "gpx.ansan": "Ansan Jarak Trail", "gpx.banpo": "Banpo Han River Park", "gpx.bukak": "Bugak Skyway", "gpx.cheonggyecheon": "Cheonggyecheon Stream", "gpx.dorimcheon": "Dorimcheon Stream", "gpx.eungbong": "Eungbongsan Stairs", "gpx.inwangsan": "Inwangsan Jarak Trail", "gpx.naksan": "Naksan Park City Wall", "gpx.namsan.north": "Namsan North Loop", "gpx.namsan.summit": "Namsan Summit Climb", "gpx.seoulsup": "Seoul Forest Loop", "gpx.tancheon": "Tancheon Stream", "gpx.yangjaecheon": "Yangjaecheon Stream", "hero0": "It’s 3 degrees Celsius with 60 percent humidity. It’s cold — muscles stiffen easily, so we’ll warm up a little longer today.", "hero1": "In 300 meters, an 800 meter climb begins. Average grade 4 percent. Shorten your stride and hold your rhythm.", "hero2": "25 seconds under target pace", "hero3": "Your heart rate is down to zone 3. You’re recovering well. Just a little more.", "hw.vs.cap1": "The first row of the table above, drawn in the app — the 7-day training-load (CTL) trend, your own 28-day range, and what the metric is.", "hw.vs.cap2": "The fourth row: race prediction and the segment pace plan.", "hw.vs.r0a": "What you have to buy", "hw.vs.r0b": "A Garmin Forerunner or a Coros is a watch you buy. Runvis runs on the Apple Watch already on your wrist; the only purchase is the coach subscription.", "hw.vs.r10a": "Coach's Brake", "hw.vs.r10b": "A budget, not a score. The last four completed weeks of distance set what this week can absorb, and the pain reports you leave after runs cut into it. The kilometres left and the kilometres the pain reports removed are shown separately, so the cut is explainable.", "hw.vs.r11a": "Coach's Record Radar", "hw.vs.r11b": "Runs with a GPS route are scanned inside the run for the fastest stretch at each distance; runs without a route are projected from the finishing average pace. Each record says which of the two it is. The window is the last 90 days.", "hw.vs.r7a": "Intensity mix", "hw.vs.r7b": "When a run has a heart-rate series and your maximum heart rate was actually observed, its minutes are split into easy, moderate and hard at 78% and 88% of maximum. Without the series — or with only the age-formula maximum — the run’s single average heart rate picks the band, and an interval session can then land in the grey middle; the screen says which of the two it used.", "hw.vs.r8a": "Hill exposure", "hw.vs.r8b": "Total ascent divided by total distance over the last 28 days, counting only runs that climbed (at least two of them): metres per kilometre. 15 and above is rolling, 40 and above is hilly. It describes the ground you ran, not you.", "hw.vs.r9a": "Heat exposure index", "hw.vs.r9b": "How much outdoor running you have stacked up above 22°C (or the same temperature in Fahrenheit, if that is your unit setting) over four weeks, on a 0–100 scale. It appears after three hot-weather runs and falls again after three days off. It is exposure, not a measurement of physiological adaptation.", "hw.vs.tm": "Garmin, Forerunner and Coros are trademarks of their respective owners. Runvis is not affiliated with either company. Only published facts are stated here — neither company publishes its formulas, so no accuracy comparison is made.", "hz.cap": "The same zones the calculator below works out, drawn on the watch while you run.", "meta.desc": "You don’t need a second running watch. Runvis reads the sleep and heart rate your Apple Watch recorded, picks today’s workout, and talks you through the run. No account, no server.", "meta.ogdesc": "You don’t need a second running watch. Your coach picks today’s workout and talks you through the run.", "meta.ogalt": "Runvis share card — your Apple Watch is enough", "meta.ogtitle": "Runvis: Apple Watch running coach", "meta.title": "Runvis: your Apple Watch is enough. Apple Watch running coach", "n.after.eb": "After the run", "n.after.h2": "When you finish,<br/>you see the why behind the numbers", "n.after.h3": "Tap a metric and see it against your usual range", "n.after.honest": "<b>When a number is an estimate, we call it an estimate.</b> When there is not enough to go on we show “learning” instead of a number. Anything we cannot stand behind is not in the app.", "n.after.l1": "Training load, ACWR, and recovery time are calculated with published formulas", "n.after.l2": "Export an AI analysis report from the workout detail and paste it into whichever AI you use", "n.after.l3": "GPX export and a 3D flyover video of your route", "n.after.p": "It shows whether today’s value sits inside your 28-day range, and where it lands next to four weeks ago. You don’t need to know the terms. Every metric comes with what it means and how it was calculated.", "n.after.sub": "Splits, heart rate zones, running dynamics, and a one-line coaching note are free. Subscribe and you also get the PR book that finds your fastest stretch inside a run, a lactate threshold estimate, and this week’s distance budget.", "n.after.t1": "Workout detail report", "n.after.t1p": "Pace by segment, heart rate zone distribution, average cadence and ground contact time. Plus one line of coaching on this run.", "n.after.t2": "Body report", "n.after.t2p": "Readiness, sleep, HRV, resting heart rate, VO₂max. Tap one to open the chart and your 28-day baseline range.", "n.after.t3": "Coach records radar (fastest segments · PR book)", "n.after.t3p": "It finds the fastest 1K, 5K, 10K and half segments inside your runs over the last 90 days, even when the run was a different distance. It also shows the gap to your previous best.", "n.after.t4": "Lactate threshold estimate", "n.after.t4p": "It estimates threshold pace and heart rate from two or more best 30-minute stretches in your last 90 days of running. Once a maximum heart rate is set, only stretches held above 85% of it qualify.", "n.after.t4h": "What if there is no 30-minute stretch?", "n.after.t4g": "With no 30-minute stretch it falls back to a 20-minute one. Failing that, it estimates from the whole-run average of three runs of 20 minutes or more held above 85% of your maximum heart rate, and that last path only works with a maximum heart rate set. It always writes on screen which of the three it used.", "n.beta.window": "There is no opening date yet. The day there is one, this paragraph becomes that date — if you see no date here, it has not been set. Until then there are two things you can do: take your place in the queue (the beta build has every coach feature switched on, free, for as long as the beta runs), or <a href=\"run.html\">run the 5K demo</a> right now and hear when and how the coach talks.", "n.faq.a5h": "What do the tests actually hold?", "n.faq.a5g": "The four translation tables must agree key for key and placeholder for placeholder, and every line written in a table must be reachable through the lookup the app actually uses. The iPhone coach’s 45-minute replay runs in six languages × metric and imperial, and one mismatch fails on the spot. Cues with numbers in them are spoken in each language’s own word order too (splits, hill warnings, pace, heart-rate zone and training steps included).", "a11y.watchstack": "Three Apple Watch running screens, cycling", "n.after.t5": "Coach brake", "n.after.t5p": "It looks at your last four weeks of training and tells you how much distance is okay this week. If you say something hurts, it lowers that number.", "n.after.t6": "Runvis VDOT", "n.after.t6p": "It works VDOT back from your best efforts and predicts your times at each distance. You see it side by side with Apple Watch VO₂max.", "n.beta.cta2": "Get the launch notice", "n.beta.eb": "Join the beta", "n.beta.gpx": "The GPX files for the 13 Seoul courses the app uses. No signup, no install — download them now and load them into another watch or map app. Distances are written in km in all six languages: a GPX file carries no unit of its own, and the device you load it into does the converting.", "n.beta.gpxattr": "Routes from OpenStreetMap road and path data; elevation from Copernicus DEM / NASA SRTMGL1 (public domain). © OpenStreetMap contributors · ODbL 1.0.", "n.beta.gpxh": "If you run in Seoul — 13 course GPX files", "n.beta.h2": "Try it first in the beta", "n.beta.nowh": "What you can look at right now", "n.beta.required": "(Required) I agree to my email being collected and used to send the beta invite.", "n.beta.s1": "Signed up — we take only your e-mail address. There is no account to create.", "n.beta.s2": "TestFlight invitation — when the beta opens, invitation links go out in the order they were requested. Apple caps external testers at 10,000 seats. All you need is an Apple account, and there is nothing to pay: on a beta build every coach feature is free for the length of the beta. Unless you opt into marketing mail, that one invitation is the only e-mail you get.", "n.beta.s3": "Feedback — send it from inside the app, or to help@runvis.app.", "n.beta.s4": "Launch — the launch date is decided after the beta ends. Korea’s App Store comes first and other regions open in stages.", "n.beta.stepsh": "What happens after you sign up", "n.beta.sub": "Leave an email address and you get one invitation when the TestFlight beta opens. The day the opening date is set, it goes here and to every address already on the list.", "n.beta.want": "What would you like to get?", "n.beta.want1": "Join the beta — send me the TestFlight invite", "n.beta.want2": "Launch notice only — tell me once when it ships", "n.beta.do1": "<a href=\"run.html\">The 5K demo</a> — hear exactly when the coach speaks and when it stays quiet, and where the free cues end and the subscription ones begin.", "n.beta.do2": "<a href=\"how-it-works.html#zones\">The heart-rate zone calculator</a> — your five zones, worked out here with the same Karvonen formula the coach’s voice uses. Your age and resting heart rate are all it needs.", "n.beta.do3": "<a href=\"how-it-works.html#gpx\">Thirteen Seoul course GPX files</a> — download them now, with no install, and load them into the watch or map app you already use.", "n.beta.do4": "<a href=\"how-it-works.html#beta\">What signing up leads to</a> — the four steps: sign-up, TestFlight invitation, feedback, launch. In the beta build every coach feature is free for the length of the beta.", "n.beta.do5": "<a href=\"privacy.html\">The privacy policy</a> — what this form collects, and how far anything the app holds ever leaves the device. Both written down.", "n.faq.a1": "The iPhone alone records GPS and calls your split pace every kilometre — every mile if that is your unit setting. Without a subscription that split is the only thing the phone says. With a subscription the phone also coaches your pace; the heart-rate zone calls need a heart rate, and an iPhone has no heart-rate sensor, so they arrive only when a Bluetooth chest strap (a standard BLE heart-rate band such as a Polar H10 or Wahoo TICKR) is connected. Form coaching, hill warnings and off-route alerts exist only on a watch run.", "n.faq.a10": "Not yet. Watch face complications, an iPhone home screen widget and Live Activities are not in this build. They are planned, but there is no date.", "n.faq.a2": "watchOS 10 or later (Apple Watch Series 4 and up) and iOS 17 or later. Past that line, heart rate and GPS are all it needs. On newer models that measure ground contact time and vertical oscillation the form coaching is finer; on the others it works from cadence.", "n.faq.a3": "Your runs stay in Apple Health, untouched. After cancelling you keep recording, plan viewing and the workout detail report for free.", "n.faq.a4": "There is no account and no server. Location leaves only for weather, the neighbourhood name and auto-generated routes. Beyond that there are App Store payments, the download of the public course and shoe list files, and — on the Korean App Store only, for now — an external shoe-search page that opens when you tap it yourself on the shoes screen. Workout and health data are never uploaded.", "n.faq.a5": "Every line the iPhone coach speaks is pinned by a test in all six languages — a 45-minute run is replayed second by second on each build to check that every cue it produces is translated. The watch’s live coaching loop sits outside that test bundle, so a line can still be missing from the tables; when one is, you hear English, never Korean, and that fallback is pinned by a test as well. The text drawn on the app’s screens uses a different table from the coach’s voice.", "n.faq.a6": "Yes. One 12-minute test run on the watch produces an estimated 5K and 10K time and your first plan the same day — that test is watch-only. With the iPhone alone you still get GPS recording, split pace cues and the training plan from day one, and the plan starts from your recent weekly distance instead. Readiness needs nights slept with the watch before its baseline exists, so it usually appears around two weeks in, and ACWR around four. Performance condition appears once you have set a maximum heart rate and logged three runs longer than ten minutes, with heart rate, in the same intensity band (easy, moderate or hard). For the first few the comparison runs against a baseline not yet separated by intensity or by the point of the run it was read at, and the app writes that on the screen itself.", "n.faq.a7": "Only accounts the App Store still counts as eligible for this subscription’s introductory offer. If you have subscribed before or already used the trial, you are charged from the first payment. The app’s purchase screen always tells you which case you are in before you buy. As configured today the free period is 1 month on the monthly plan and 1 month on the yearly one; picking yearly does not make a year free. The length itself is sent down by the App Store with the product, so the app shows you exactly what it received, right before the purchase. On yearly, the whole year is charged once that 1 month ends.", "n.faq.a8": "The lifetime pass is a one-time purchase with no auto-renewal. By the maths on the price card it breaks even at about 2.6 years against yearly, or about 20 months against monthly, so if you expect to use Runvis longer than that, lifetime is the cheaper side. It is also the only plan Apple Family Sharing covers — the monthly and yearly subscriptions are not eligible.", "n.faq.a9": "The runs themselves live in Apple Health, so the Health app on the new device brings them across. What lived only inside Runvis — your profile, heart-rate zones, shoe list and the baselines the coach built — goes out as a single file from Settings → Data → ‘Export my data’, and comes back on the new device with ‘Import from backup’. The file stays only where you put it; Runvis sends it nowhere. The subscription comes back through the App Store’s restore purchases.", "n.faq.eb": "Common questions", "n.faq.h2": "What people ask first", "n.faq.q1": "Do I need a watch?", "n.faq.q10": "Is there a watch face complication or a widget?", "n.faq.q2": "Which Apple Watch do I need?", "n.faq.q3": "What happens to my data if I cancel?", "n.faq.q4": "Where does my data go?", "n.faq.q5": "How complete are the six languages?", "n.faq.q6": "Can I start with no history at all?", "n.faq.q7": "Who gets the free trial?", "n.faq.q8": "Lifetime or yearly — which is better?", "n.faq.q9": "What happens when I change device?", "n.hero.b1": "all on device — lookups excepted", "n.hero.b1n": "Analysis", "n.hero.b3": "Coach voice · exceptions in the FAQ", "n.hero.b3n": "6 languages", "n.hero.b5": "about US$1.40 · recording stays free", "n.hero.b5n": "₩1,900/mo", "n.hero.cta1": "Join the beta", "n.hero.cta2": "Run the 5K demo", "n.hero.eb": "Apple Watch running coach", "n.hero.h1": "Your Apple Watch<br/><span class=\"grad\">is enough</span>", "n.hero.note": "Recording is free. The coach is a subscription; all three prices are in the table below. Runvis opens on the Korean App Store first, and other regions follow.", "n.hero.sub": "You don’t need a second running watch. Your coach reads the data already on your wrist, picks today’s workout, and talks you through the run.", "n.live.demo": "See when it speaks and when it stays quiet in the 5K demo", "n.live.eb": "While you run", "n.live.h2": "Only what you need,<br/>right when you need it", "n.live.q.h": "It does not talk much", "n.live.q.moreh": "The per-session table and every exception", "n.live.q.n1": "The floor is 45 seconds between cues. Safety calls, core calls such as workout steps, and splits do not wait for it — and neither do the items below.", "n.live.q.n2": "Splits, hill warnings and the auto-pause and resume calls each follow a rule of their own and never draw on the 30-minute cap. The walk-to-run change and the breathing count are outside the 45-second rule too — late, they mean nothing. So is the greeting when it recognises a route you have run before.", "n.live.q.n3": "Running with the iPhone alone the rules differ — there are fewer cues, so how often it speaks comes from a 20-second gap instead of 45, a 3-minute cooldown on pace and a 5-minute one on heart-rate zone, with no 30-minute cap at all.", "n.live.q.n4": "8 items switch on and off one by one: pace, heart-rate zone, form, hills, encouragement and scripts, running-tip cards, hydration, and the auto-pause/resume voice. Splits are not a switch but an interval — off, 0.5 or 1 (km or miles). Safety calls and core calls such as workout steps cannot be switched off. Music only dips while the coach is speaking.", "n.live.q.r1a": "Easy · long · run-walk", "n.live.q.r1b": "up to 8", "n.live.q.r2a": "Tempo · race · free run", "n.live.q.r2b": "up to 6", "n.live.q.r3a": "Intervals", "n.live.q.r3b": "no cap — what you leave switched on decides how often it speaks. In exchange, intervals carry only the step, heart-rate zone, pace and auto-pause cues: splits, hills, form and encouragement stay quiet", "n.live.q.th1": "Session", "n.live.q.th2": "Other cues per 30 min (excl. splits, hills, pauses)", "n.live.siri": "Say “Hey Siri, Start a run with Runvis” and the start screen opens straight away. The spoken phrases exist in all six languages.", "n.live.sub": "Everything the coach says starts from something the sensors picked up. Tap to hear the real guidance.", "n.nav.after": "After", "n.nav.cta": "Join the beta", "n.nav.demo": "5K demo", "n.nav.faq": "FAQ", "n.nav.live": "While you run", "n.nav.price": "Pricing", "n.nav.race": "Race", "n.nav.today": "Today", "n.nav.why": "Why", "n.pill.free": "Free", "n.pill.pro": "Subscription", "n.price.cancel": "You can cancel in your App Store account settings at any time. Cancelling keeps access until the period ends and stops the renewal. Refunds follow Apple’s refund policy.", "n.price.cta": "Try it first in the beta — or just get the launch notice", "n.price.eb": "Pricing", "n.price.f1": "GPS tracking, pace, heart rate, laps, saved to Apple Health", "n.price.f2": "Workout detail report, body report, run history", "n.price.f3": "Plan viewing, basic race predictions, the weather briefing and warm-up screen, race mode on the watch with your personal-best ghost", "n.price.f4": "Running with the watch: voice for splits (in your unit setting), heart-rate zones, pace, climb warnings and off-route alerts", "n.price.f4b": "Running with the iPhone alone, splits are the only free voice", "n.price.f5": "GPX export, AI analysis report", "n.price.freeName": "Basic", "n.price.freecta": "See how far the free tier goes in the 5 km demo", "n.price.gateh": "When do the numbers appear?", "n.price.gatelead": "All seven unlock the moment you pay, and then fill in as runs accumulate. Until then each tile writes down what it is still waiting for.", "n.price.g1": "Lactate Threshold (est.) — two 30-minute (or 20-minute) stretches held above 85% of your maximum heart rate. With only runs that record no route, it is computed from a maximum heart rate you have set plus three runs of 20 minutes or more.", "n.price.g2": "Endurance training volume — 6 runs across 3 of 4 weeks, spread over at least two weeks.", "n.price.g3": "Hill exposure — 2 climbing runs.", "n.price.g4": "Heat exposure index — 3 runs on days above 22°C.", "n.price.g5": "Intensity mix — 8 days including 5 runs with heart rate.", "n.price.g6": "Coach's Brake — 2 weeks of running.", "n.price.g7": "Coach's Record Radar — records start being caught from a single run of 1 km or more.", "n.price.h2": "Recording is free —<br/>you only pay for the coach", "n.price.life": "Instead of subscribing, <b>a lifetime pass for ₩39,000</b> — a launch price. If it rises later, the rise never reaches anyone who already bought. At Korean App Store prices that works out to roughly 2.6 years of the yearly plan, or about 20 months of the monthly one; your own store’s price points can land on a different ratio. It is the only plan Apple Family Sharing covers.", "n.price.p1": "The coach’s voice while you run: form, how to run the hills, recovery, encouragement", "n.price.p2": "Plan execution: every segment driven, then a score against the plan", "n.price.p3": "Seven deep-analysis tiles open in the report", "n.price.p4": "Race strategy: a segment pace plan, a fuelling schedule, a race rehearsal", "n.price.p5": "The weekly coach summary card: plan-adherence score, this week’s fastest segment, the running budget you have left, the last four weeks’ intensity mix, and one line on what to change next week. Free accounts see this card as a locked preview.", "n.price.p6": "Runvis VDOT, back-solved from your best effort, predicts times from 5K to the marathon", "n.price.t1": "Lactate Threshold (est.)", "n.price.t2": "Endurance training volume", "n.price.t3": "Hill exposure", "n.price.t4": "Heat exposure index", "n.price.t5": "Coach's Brake", "n.price.t6": "Intensity mix", "n.price.t7": "Coach's Record Radar (fastest segments, last 90 days)", "n.price.sub": "Recording, viewing plans, and reports are free. The coach speaking to you and the deeper analysis are the subscription. Runvis launches on the Korean App Store first, where the coach is ₩1,900 a month; in every other region your own App Store’s price applies, and the exact figure for your store goes on this page the day it is set. Accounts the App Store judges eligible get 1 month free — the same 1 month whether they pick monthly or yearly.", "n.price.year": "Yearly is <b>₩15,000</b> — about ₩1,250 a month, roughly 34% less than paying monthly on the Korean App Store. Other stores price in their own tiers, so that ratio can come out differently; the app’s purchase screen works the real saving out from the two prices it is offered. On an eligible account the yearly plan comes with a free period too, but it is 1 month long — the same as monthly, not a year. When that month ends, the whole ₩15,000 year is charged at once.", "n.priv.big": "No account, no server.<br/>The coach still talks in a tunnel.", "n.priv.eb": "Privacy", "n.priv.link": "Privacy Policy", "n.priv.p": "Recording and analysis all happen on the watch and the iPhone. Weather look-ups send coordinates rounded to about a kilometre; the neighbourhood name and auto-generated routes send your current coordinates to Apple services, only at that moment. Beyond those there are App Store payments, the download of the public course and shoe list files, and — on the Korean App Store only, for now — an external running-shoe search page that opens when you tap it yourself on the shoe screen. Every one of those exceptions is written out in the privacy policy. Your workout and health data are never uploaded.", "n.race.eb": "Race prep", "n.race.h2": "A week-by-week plan up to race day,<br/>a segment strategy on the day", "n.race.h3": "Pick a coach and the plan and the tone change with it", "n.race.h3b": "A coach who knows the race course in advance", "n.race.l1": "The coach drives each interval segment, then scores the session against the plan", "n.race.l2": "On an off day, one tap lowers the intensity and rebuilds the plan", "n.race.l3": "With no race times on file, one 12-minute test run on the watch builds your first plan", "n.race.lb1": "One recent result gives you predicted times and target paces for the 5K, 10K, half, and full", "n.race.lb2": "Run the same course again and your best becomes a ghost that tells you the gap", "n.race.lb3": "From 15 days out, a predicted time that factors in the race-day forecast", "n.race.p": "Finish first, balanced, or chasing a time. Pick one of the three and both the training mix and the tone during the run change together. If you’re new, no coach will hand you intervals that are too much.", "n.race.pb": "Load the race GPX and it knows where the climbs come before you do. Send grade-aware segment paces and fueling points to the watch, and on race day you just follow the guidance.", "n.race.sub": "Enter your goal race and target time and it builds a week-by-week roadmap. It also tells you honestly whether that target fits your current fitness. Viewing the plan is free. Having the coach run you through each segment on the watch is part of the subscription.", "n.st.caution": "Caution", "n.st.fair": "Fair", "n.st.good": "Good", "n.step1h": "Weather briefing", "n.step1p": "Live weather for the neighborhood you’re in right now.", "n.step1q": "“It’s 26 degrees Celsius with 78 percent humidity. Hot and humid — evaporation is working against you.”", "n.step2h": "Warm-up", "n.step2p": "A timer leads you through each stage, and the coach talks you through them when it is on.", "n.step2q": "“Hip circles, 20 seconds. Now the other way. Three, two, one.”", "n.step3h": "Just run", "n.step3p": "It senses the running rhythm at your wrist and starts recording.", "n.step3q": "“You’ve started running. Recording now.”", "n.steps.h": "You press start once", "n.steps.note": "The screen, the timer and the auto start are free. The coach walking you through it by voice is the subscription.", "n.today.eb": "Today’s decision", "n.today.h2": "Open it in the morning<br/>and today’s workout is set", "n.today.h3": "The decision first, the reasons below it", "n.today.l1": "On an off day it lowers the intensity and tells you why", "n.today.l2": "If you don’t like the easier version, you can keep the original workout", "n.today.l3": "When there isn’t enough data, it shows “Learning” instead of a number", "n.today.m1": "Sleep", "n.today.m3": "Yesterday’s load", "n.today.p": "Today’s workout sits at the top. The reasoning behind it sits right under. The rest of the metrics move down as reference. Tap a metric to see what it means, how it is calculated, and your usual range.", "n.today.siri": "You can hear it without waking the watch — say “Hey Siri, What should I run today with Runvis” and today’s call is read back to you. Readiness and this week’s plan answer the same way.", "n.today.sub": "It compares last night’s sleep, HRV, resting heart rate, and yesterday’s training load against your own 28-day baseline. Then it picks today’s workout and adds one line on why.", "n.today.w1": "Today’s decision", "n.today.w1p": "The readiness ring and today’s workout show up right on your wrist.", "n.today.w2": "Today’s reasons", "n.today.w2p": "Sleep, HRV, and yesterday’s load are compared with your baseline and marked Good, Fair, or Caution.", "n.today.w3": "Start in one tap", "n.today.w3p": "Today’s workout sits at the top of the start screen. Tap it and the coach runs you through each segment.", "n.trust.h": "What can be checked right here, today", "n.trust.l1": "766 automated tests check the coach’s spoken lines, the free/paid boundary and the plan maths on every build.", "n.trust.l2": "2,341 interface strings line up key for key across all six language tables, and the four coach-voice tables hold 396 lines each. One mismatch and the test fails on the spot.", "n.trust.l3": "41 metric explanations ship inside the app — tap a number you do not know and you get its meaning, how it was calculated and your own usual range.", "n.trust.p": "One person builds this app. There are no ratings and no press yet — it has not shipped. So instead of numbers that could be invented, these are counted straight out of the app’s repository. Anything else you want to know, write to help@runvis.app; the reply comes from me.", "n.vc1.aria": "Play sample voice: pace call (free)", "n.vc1.line": "“25 seconds under target pace”", "n.vc1.play": "Pace", "n.vc1.sensor": "📡 When you stay more than 20 seconds off target pace for over 20 seconds", "n.vc2.aria": "Play sample voice: hill warning (free)", "n.vc2.line": "“In 300 meters: a climb of 800 meters, averaging 4 percent. Shorten your stride, keep the rhythm.”", "n.vc2.play": "Hill warning", "n.vc2.sensor": "📡 It reads the course elevation ahead. On a road you run often, it recognises it around 500m in and calls the hills", "n.vc3.aria": "Play sample voice: stride cue (subscription)", "n.vc3.line": "“Cadence is 5 percent under your baseline — let’s shorten the stride a touch.”", "n.vc3.play": "Stride", "n.vc3.sensor": "📡 Stride cue · only on the flat at a steady pace. Cadence between 130 and 160 spm and 5% under your own baseline, held for 30 seconds. Ground contact over 300 ms or a bigger vertical bounce produces the same line (those two carry no cadence ceiling). From six minutes in, 2 times a run at most. The “Form” switch in Settings turns this cue and the form cue on together.", "n.vc4.aria": "Play sample voice: recovery call (subscription)", "n.vc4.line": "“Heart rate is down to zone 3. You’re recovering well — almost there.”", "n.vc4.play": "Recovery", "n.vc4.sensor": "📡 When your heart rate zone drops one step during a walk recovery", "n.why.c1h": "The sensors are already on your wrist", "n.why.c1p": "Heart rate, GPS, cadence, altitude. Recent watches also measure ground contact time and vertical oscillation.", "n.why.c2h": "The formulas are public", "n.why.c2p": "Training load, recovery time, and threshold estimates come from published sports science formulas. Runvis runs those formulas on your device.", "n.why.c3h": "What was missing was the coach", "n.why.c3p": "Someone to read the numbers, pick today’s workout, and talk to you while you run. That is the part Runvis does.", "n.why.eb": "Why Runvis", "n.why.h2": "You don’t need to buy<br/>a second running watch", "n.why.phone": "You don’t need a watch yet. The iPhone alone records GPS and calls your split pace every kilometre — every mile if that is your unit setting — and without a subscription that split is the only thing it says. Form coaching needs the wrist sensors, so it stays on the watch.", "n.why.s1": "Entries with a plain-language note", "n.why.s1n": "on device", "n.why.s1v": "41", "n.why.s2": "Coach lines written", "n.why.s2n": "all six languages", "n.why.s2v": "287", "n.why.s3": "Automated tests", "n.why.s3n": "every build", "n.why.s3v": "766", "n.why.sub": "People say you need a dedicated running watch — a Garmin Forerunner, a Coros — to see metrics like training load and recovery time. But the sensors those numbers come from are already in the Apple Watch.", "nf.title": "Nothing lives at this address — Runvis", "nf.h1": "Nothing lives at this address", "nf.p": "The link may have changed, or the address may have been copied wrong. This site is five pages, and three of them are below.", "nf.l1": "Home", "nf.l2": "Run the 5K demo", "nf.l3": "The rules and the tools", "ph.email": "Email address", "pl.coach": "Runvis Coach", "pl.ribbon": "Eligible accounts: 1 month free", "pl.terms": "Who is eligible?", "pr.approx": "That is the Korean App Store price — Korea is the launch store. Anywhere else you are charged your own App Store’s local price.", "pr.approxref": "If you are reading this outside Korea, take these as size only: ₩1,900 a month is about US$1.40, ₩15,000 a year about US$11, and the ₩39,000 lifetime pass about US$28. That is a size, not a bill.", "pr.free": "Free", "pr.launch": "Runvis launches on the Korean App Store first; other regions will follow over time. The launch date is set after the TestFlight beta ends, and it will be written on this page first.", "pr.month": "₩1,900", "pv.back": "← Back to Runvis", "pv.h1": "Privacy Policy", "pv.legalNote": "The Korean version is the legally binding text. Other languages are translations provided for convenience; if they differ in meaning, the Korean version prevails. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.meta.desc": "Runvis processes running and health data on your device only. No server, no account, and every exception that leaves the device is written out here.", "pv.meta.title": "Privacy Policy — Runvis", "pv.s1.h": "1. Data collected and processed", "pv.s1.li1": "<b>Workout data</b>: heart rate, pace, distance, GPS route, elevation, cadence, running power, stride length, ground contact time and vertical oscillation (on supported devices), calories — read from and written to Apple HealthKit", "pv.s1.li2": "<b>Health data</b>: sleep (duration and stages), heart-rate variability (HRV), resting heart rate, VO₂max and, if you choose, menstrual cycle — used for training readiness and recovery analysis", "pv.s1.li3": "<b>Motion data</b>: wrist acceleration (to detect the start of a run automatically) and, when worn, AirPods head motion — used as a supporting form signal", "pv.s1.li4": "<b>Profile entries</b>: year of birth, sex, resting heart rate and maximum heart rate — entered by you on the first setup screen and used only as the basis for heart-rate zones and age-based estimates", "pv.s1.li5": "<b>Other entries</b>: target race and goal time, coach tone, shoe details, and the post-run check-in (effort, pain, hydration)", "pv.s1.li6": "<b>Bluetooth sensors</b>: when connected, live readings from a heart-rate strap, cycling power meter or smart trainer", "pv.s1.li7": "<b>Diagnostics</b>: crash and hang reports (Apple MetricKit) — stored on the device only, and they leave it solely when you export or share them yourself", "pv.s1.p": "Runvis reads and processes the following data <b>on the device</b>. All of it serves app functionality, and none of it leaves the device.", "pv.s10.h": "10. Changes and contact", "pv.s10.p": "When this policy changes, the effective date on this page is updated. For the terms of service, see the <a href=\"terms.html\">Terms of Service</a>. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s2.h": "2. Where the data is stored", "pv.s2.li1": "Workouts and routes are stored in <b>Apple Health (HealthKit)</b> — you own them, and whether they sync via iCloud Health follows your iOS settings", "pv.s2.li2": "App settings, profile entries, plans, courses and badge calculations live <b>only in the app’s on-device storage</b>", "pv.s2.li3": "Runvis operates no server, no database and no account system of its own", "pv.s2.li4": "Runvis performs no backup or sync of its own. Move to a new device and the workouts stored in Apple Health come with you, but the values that live only in the app’s own storage — profile, shoes, plan, badges and the baselines the coach built — do not. Settings → Data → ‘Export my data’ writes those values to a single file that ‘Import from backup’ restores on the new device; that file stays only where you put it and Runvis sends it nowhere", "pv.s3.h": "3. Everything that leaves the device (complete list)", "pv.s3.note": "None of the above carries identifying information such as a name or e-mail address, and Runvis keeps no separate log of it. Runvis <b>does not upload</b> the workout and health data it records — the app contains no code to do so, and every request above is a read-only lookup carrying only the minimum needed for that lookup.", "pv.s3.r1a": "Weather briefing", "pv.s3.r1b": "Coordinates rounded to roughly 1 km (neighbourhood-level precision) plus the time — only at the moment of the request, with no storage and no identifier", "pv.s3.r1c": "Open-Meteo (free weather API)", "pv.s3.r2a": "Subscription payment", "pv.s3.r2b": "The entire payment process — Runvis can neither see nor store card or payment details", "pv.s3.r2c": "Apple App Store", "pv.s3.r3a": "Automatic route generation", "pv.s3.r3b": "Your current coordinates for the route calculation — only at the moment you request a route, and not rounded", "pv.s3.r3c": "Apple Maps (MapKit)", "pv.s3.r4a": "Neighbourhood name", "pv.s3.r4b": "Your current coordinates, so the weather briefing and the workout record can carry a neighbourhood name — only at the moment of the lookup, and not rounded. The result is cached on the device, so the same place is never looked up twice", "pv.s3.r4c": "Apple location services (CLGeocoder)", "pv.s3.r5a": "Course and shoe catalogue download", "pv.s3.r5b": "<b>Nothing is sent</b> — a public file is downloaded anonymously once a day (as with any website visit, your IP address is visible to the host)", "pv.s3.r5c": "GitHub Pages (static file hosting)", "pv.s3.r6a": "Opening a running-shoe search", "pv.s3.r6b": "<b>Nothing is sent</b> — only when you tap the button yourself on the shoe screen of the watch or the iPhone does an external browser open at an address carrying the search term “running shoes”. No workout, health or shoe data goes with it", "pv.s3.r6c": "An outside shop — currently the search page of the Korean retailer Coupang", "pv.s3.th1": "Exception", "pv.s3.th2": "What is sent", "pv.s3.th3": "Recipient", "pv.s4.h": "4. Why each permission is used", "pv.s4.li1": "<b>Health (HealthKit)</b>: saving workouts and analysing past records", "pv.s4.li2": "<b>Location</b>: recording the running route, the weather briefing and course guidance", "pv.s4.li3": "<b>Motion</b>: detecting the start of a run automatically and guiding the warm-up", "pv.s4.li4": "<b>Notifications</b> (optional, 9 kinds): training-plan day reminders, the evening briefing, the Sunday weekly coach summary, a comeback nudge after a long gap, a first-week note after subscribing, a note two days before a free trial or coach mode ends, a re-subscribe nudge a week after cancelling (that one is marketing), the watch’s recovery-complete alert, and the watch’s rest nudge — the wording is composed on the device and is never sent to a server", "pv.s4.li5": "<b>Bluetooth</b>: connecting external sensors (heart-rate straps, power meters)", "pv.s4.li6": "<b>Calendar</b> (optional): adding training-plan sessions to your calendar", "pv.s4.li7": "<b>Photos</b> (optional): saving the route fly-over video", "pv.s4.note": "You can decline any permission; only that specific feature is affected, and the rest of the app keeps working.", "pv.s5.h": "5. Third parties, advertising and tracking", "pv.s5.li1": "Sharing with third parties: <b>none</b> — this refers to the workout and health data the app processes. The one exception is the beta sign-up e-mail on the website, processed on our behalf by Formspree and described in section 6", "pv.s5.li2": "Advertising SDKs, analytics SDKs and tracking tools: <b>none</b>", "pv.s5.li3": "Sale of data: <b>none</b>", "pv.s6.h": "6. The website (beta sign-up)", "pv.s6.li1": "<b>What is collected</b>: the e-mail address, and only the one you type in yourself", "pv.s6.li2": "<b>Purpose</b>: sending the TestFlight beta invitation and notices about the beta", "pv.s6.li3": "<b>Processor and international transfer</b>: form delivery and storage are handled by <b>Formspree, Inc.</b> (USA), so the address you submit is transmitted to and stored on Formspree servers in the United States — <a href=\"https://formspree.io/legal/privacy-policy/\" rel=\"noopener\">Formspree privacy policy</a>", "pv.s6.li4": "<b>Retention and deletion</b>: the address is deleted without delay once its purpose is fulfilled (the beta invitation has been sent), and in any case within one year of collection. To request deletion: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s6.p": "If you submit an e-mail address through the beta sign-up form on runvis.app, it is handled as follows. This section applies to the website form only; the app collects no account information at all, e-mail included.", "pv.s7.h": "7. Deleting your data", "pv.s7.p": "Deleting the app deletes everything in its storage, profile entries included. Workouts saved to HealthKit belong to you, so they remain in the Health app after the app is gone; you can delete them there yourself.", "pv.s8.h": "8. Children", "pv.s8.p": "Runvis is not intended for children under 14. The first setup screen asks for your year of birth so heart-rate zones and age-based estimates can be calculated, but that value is stored on the device only and is never transmitted. If a child uses the app through a Family Sharing subscription, parental guidance is required.", "pv.s9.h": "9. Medical disclaimer", "pv.s9.p": "Every number and cue in Runvis is an <b>estimate for reference</b>, derived from published sports-science formulas. None of it is a medical diagnosis, treatment or prescription. If you experience symptoms such as chest pain or dizziness, stop exercising immediately and consult a professional.", "pv.summary": "<b>In one paragraph</b> — Runvis processes your running and health data <b>only on your device</b>. There is no Runvis server and no account, and your workout and health data is never transmitted, sold or shared with anyone, the developer included. Every exception (weather lookup, Apple payments, map route generation, neighbourhood name lookup, downloading the public course and shoe list files, and the running-shoe search link you tap yourself) is spelled out below.", "pv.updated": "Effective: 6 September 2026 · version 1.3", "r.alt.elev": "Elevation profile for the next 1.5 kilometres — a climb starts 300 metres ahead, 34 metres of total gain", "r.alt.watch": "Apple Watch screen — today’s goal 5.0 kilometres, run with Runvis", "r.badge.note": "Every coach cue below is tagged <span class=\"pill free\">Free</span> or <span class=\"pill pro\">Subscription</span>. Recording, laps, saving to Apple Health, browsing your history, viewing the training plan, the detailed run report and the warm-up screen are all free.", "r.hud.dist": "DIST", "r.hud.hr": "HR", "r.hud.pace": "PACE", "r.hud.zone": "ZONE", "r.rail.aria": "Run session sections", "r.signup.h": "You made it to 5 km", "r.signup.p": "If you want to hear what you just read on your wrist, sign up right here — no need to go back to the home page. We write to this address the day the opening date is set, and invites go out in signup order.", "r.signup.price": "See the pricing", "r.tier.free": "GPS recording, laps, saving to Apple Health and full access to your history · viewing the training plan · the detailed run report · the warm-up screen · running with the watch: voice for kilometre (or mile) splits, heart-rate zones, pace, course climb warnings and off-route alerts (with the iPhone alone, splits are the only free voice) · the post-run tip card · race mode and the ghost display", "r.tier.price": "Choose monthly at ₩1,900, an annual subscription, or a lifetime pass. Prices follow the App Store. There is no account and no server — your data stays on the device and in Apple Health.", "r.tier.pro": "Form-coaching voice plus hill technique, recovery and encouragement cues · running the training plan step by step, with a plan-adherence score at the end · the seven deep-analysis tiles · race strategy (rehearsal, segment pace plan, fuelling schedule) · the weekly coach summary card", "r.unitnote": "This demo runs in kilometres only. The app itself follows your device’s unit setting — splits every 1 km or every 1 mile, with the distances and paces on screen and in the voice in that same unit.", "r.silence": "{km} km to the next intervention · the only voice in this stretch is the kilometre split", "r.warmup.v": "6 STEPS", "r1": "RUN SESSION — 5km with Runvis | Runvis", "r10": "RUNVIS // LIVE COACHING DEMO", "r11": "Today’s run,<br><span class=\"outline\">with a coach</span>.", "r12": "From here on, <b>scrolling is running</b>. Scroll down and a 5km run begins — the distance, pace and heart rate at the bottom move with you. See for yourself <b>when, and why, Runvis speaks up</b> — and when it stays quiet.", "r13": "The numbers on this page are sample data for the demo · the real app runs on Apple Watch sensors", "r14": "kilometers · today’s goal", "r15": "Run with Runvis", "r16": "Briefing · Warm-up · Coaching", "r17": "SEGMENT 00 — FRONT DOOR · 05:52 AM", "r18": "Before you run,<br><span class=\"grad\">the coach speaks first</span>", "r19": "One tap on start and it flows from <b>weather briefing → warm-up</b>. No server of ours — right on the watch.", "r2": "Scrolling is running. Experience 5km for yourself and see when — and why — Runvis steps in, from warm-up to finish.", "r20": "“Hi, this is Runvis. Ready to run together? Weather in Yeouido-dong. It’s 26 degrees Celsius with 78 percent humidity. Hot and humid — evaporation is working against you. Hydrate per sports-science guidance: 150–200 milliliters every 15 minutes, roughly every 3 kilometers. Small sips, spread out. That’s the briefing. Tap Start Warm-up on screen and let’s loosen up.”", "r21": "WHY · <b>Your neighbourhood name + live Open-Meteo weather</b> → a hydration guide built from the sports-science temperature × humidity rule. On hot days the in-run drink reminders come closer together too. The weather screen and the warm-up timer are free; having this read aloud is the subscription", "r22": "For the weather, rounded coordinates go to Open-Meteo; for the neighbourhood name, your current coordinates go to Apple location services, only at that moment.", "r23": "SEGMENT 01 — 0.0 → 1.0 KM", "r24": "No button needed.<br><span class=\"outline\">Run, and it knows</span>", "r25": "Finish your warm-up and simply start running — Runvis <b>detects the run automatically</b> and begins recording and coaching.", "r26": "“Today’s condition briefing. You slept 7 hours 24 minutes. Resting heart rate is below your baseline — a good sign.”", "r27": "WHY · The wrist accelerometer rhythm <b>detects the run automatically</b> and starts recording (free) · The condition briefing comes 8 seconds after the start, and only when resting HR is 5 above or 3 below your baseline, or you slept under 6 hours. On an ordinary day it says nothing", "r28": "−4 (BELOW BASELINE)", "r29": "SEGMENT 02 — 1.0 → 2.5 KM · THE CLIMB", "r3": "START", "r30": "A hill you <span class=\"grad\">see coming</span><br>is nothing to fear", "r31": "Load the race GPX course and Runvis warns you about <b>the climb you can’t see yet</b>.", "r32": "“In 300 meters, an 800 meter climb begins. Average grade 4 percent. Shorten your stride and hold your rhythm.”", "r33": "WHY · It reads the course elevation ahead. With the coach on, it uses <b>grade-adjusted pace</b> on climbs to tell you whether your current speed is okay", "r34": "SEGMENT 03 — 3.0 → 4.0 KM · FATIGUE SETTING IN", "r35": "When the going gets hard,<br>it steps in <span class=\"outline\">with evidence</span>", "r36": "Not “your form is bad” — a form cue that tells you <b>what changed, and by how much</b>.", "r37": "“Your steps are 7 percent slower and ground contact 10 percent longer than when you started. Shorten your stride and your turnover — and your form — will come back.”", "r38": "WHY · form cue — a different cue from the stride cue, with its own rule · watches that measure ground contact: two of cadence, ground contact and vertical oscillation drifting together, or one drifting far, held for 30 seconds · watches that measure cadence only: a 6% cadence drop held for 60 seconds · either way, only on flat ground at a steady pace · the one “Form” switch in Settings covers this cue and the stride cue · once it has spoken it stays quiet until the drift settles", "r39": "“Good — your form is coming back. Hold that feeling just a little longer.”", "r4": "BRIEFING", "r40": "WHY · Only on a run where you <b>actually heard the warning</b> · Once, two minutes after the warning and only when the drift has fallen clearly below its peak. If the spacing rule swallowed the warning, no praise follows either", "r41": "SEGMENT 04 — 4.0 → 4.5 KM · WALK BREAK", "r42": "Walking is<br><span class=\"grad\">part of the training</span> too", "r43": "If you’re spent, walk. Runvis doesn’t call it stopping — it <b>works through the recovery with you</b>.", "r44": "“You’ve started walking — catching your breath is a good call. Jog again when you feel ready, or keep walking if you need to. I’ll let you know when your heart rate drops to zone one.”", "r45": "WHY · It counts as walking when the speed drops into the walking band and <b>cadence stays under 130 for 8 seconds</b> — outdoors with GPS, after the first 5 minutes, and only on a free run rather than a prescribed plan. The moment the walk starts, the running cues still queued are dropped", "r46": "138 ← now", "r47": "WAITING…", "r48": "“Your heart rate has recovered. Ready to run again? Start easy.”", "r49": "WHY · While you walk it calls out <b>every zone your heart rate drops through</b>, and once you reach zone one it tells you it’s fine to run again — you <b>hear the recovery happen</b>", "r5": "SET OFF", "r50": "FINISH — 5.0 KM · MISSION COMPLETE", "r51": "The run is done.<br>The coaching <span class=\"grad\">starts here</span>", "r52": "The moment the run is saved — heart-rate zones, training load, form observations and a <b>coaching summary for your next run</b>. All of that is free. If you like, one tap exports a report you can hand to your own AI.", "r53": "Distance · Time", "r54": "Avg pace · heart rate", "r55": "Training load", "r56": "TRIMP 54 · drift +1.8%", "r57": "Coach’s line", "r58": "Heart-rate efficiency held through the second half.", "r59": "Export", "r6": "THE CLIMB", "r60": "✨ For AI analysis · GPX", "r62": "See all features", "r63": "The numbers and lines on this page are demo examples showing how the real app behaves. All metrics and guidance are reference information based on general exercise-science formulas, not medical advice.<br>Contact: <a href=\"mailto:help@runvis.app\" style=\"color:var(--dim)\">help@runvis.app</a> · © 2026 Runvis · Apple Watch is a trademark of Apple Inc.", "r7": "THE WALL", "r8": "RECOVERY", "r9": "FINISH", "sc.note": "All eleven screenshots on this page — five iPhone, six Apple Watch — were captured with the app running in your language. The mid-run screens come from a real recorded run. The app keeps being fixed after a capture is taken, so the build you install can be newer than what you see here.", "sc.note.s": "Captured with the app running in this language.", "t160": "Get a beta invite", "t161": "What we collect", "t162": "Retention period", "t163": "Privacy Policy", "t164": "Terms of Service", "t165": "help@runvis.app", "t166": "All of Runvis’s metrics and guidance are reference information based on general exercise-science formulas; they are not medical advice and do not assess your health. If you experience symptoms such as chest pain or dizziness, stop exercising and consult a professional. Apple Watch is a trademark of Apple Inc. Runvis is an independent app and is not affiliated with Apple.", "tm.back": "← Back to Runvis", "tm.h1": "Terms of Service", "tm.legalNote": "The Korean version is the legally binding text. Other languages are translations provided for convenience; if they differ in meaning, the Korean version prevails. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "tm.meta.desc": "Runvis terms of service — subscriptions and the lifetime pass, auto-renewal and cancellation, safety notes and limits of liability.", "tm.meta.title": "Terms of Service — Runvis", "tm.s1.h": "1. About the service", "tm.s1.p": "Runvis is a running-tracking and coaching app for Apple Watch and iPhone. GPS recording, laps, saving to Apple Health, browsing your history, viewing the training plan, the detailed run report and the warm-up screen are free. Form, recovery and encouragement coaching by voice, running the training plan step by step with a plan-adherence score, the deep analysis, race strategy and the weekly coach summary are provided through an in-app subscription or a lifetime pass. Runvis creates no account and operates no server of its own.", "tm.s2.h": "2. Subscriptions", "tm.s2.li1": "Payment, renewal and cancellation are handled through your Apple App Store account and follow Apple’s standard subscription terms", "tm.s2.li2": "Monthly and annual plans are <b>auto-renewing</b>. Unless you cancel at least <b>24 hours before</b> the current period ends, the subscription renews automatically, and the renewal charge is billed to your Apple account within the 24 hours before the period ends", "tm.s2.li3": "Where a free trial is offered, it converts to a paid subscription and is charged unless you cancel at least 24 hours before the trial ends. Whether a trial is offered is determined by Apple based on your account’s eligibility, and it is shown on the purchase screen only when you are eligible", "tm.s2.li4": "You can cancel any time in iOS Settings → Apple Account → Subscriptions, and you keep access until the period you already paid for ends", "tm.s2.li5": "The monthly and yearly subscriptions are not covered by Apple Family Sharing. The only product a family group can share is the lifetime pass in section 3", "tm.s2.li6": "Refunds follow Apple’s refund policy and process", "tm.s3.h": "3. Lifetime pass", "tm.s3.li1": "The lifetime pass is a <b>non-consumable product paid for once</b>, with no auto-renewal. It unlocks the same coaching features as a subscription", "tm.s3.li2": "The current price is a <b>launch price</b> and may rise later. Any increase applies <b>only to purchases made afterwards</b>; a pass already bought is never charged again", "tm.s3.li3": "The lifetime pass is covered by Apple Family Sharing, so the members of your family group can use it too — none of the subscription products are shareable", "tm.s3.li4": "Because Runvis creates no account, you restore the pass on a new device or a reinstall with <b>Restore Purchases</b> on the purchase screen. Restoring works only with the Apple account used for the purchase", "tm.s3.li5": "The lifetime pass is valid for as long as the Runvis app is offered on the App Store. If the service is discontinued, the service-limitation clause in section 5 applies alongside it", "tm.s3.li6": "Refunds follow Apple’s refund policy and process", "tm.s3.li7": "The tip jar (coffee, lunch, heart) is a <b>one-time thank-you</b> and unlocks no features at all — it is not a substitute for a subscription or the lifetime pass", "tm.s4.h": "4. Your responsibilities", "tm.s4.li1": "Exercise at your own judgement and responsibility, taking your own state of health into account", "tm.s4.li2": "When running outdoors on roads or tracks, stay aware of traffic and your surroundings at all times, and use the voice guidance at a level that does not block ambient sound", "tm.s4.li3": "If you notice symptoms such as chest pain, dizziness or difficulty breathing, stop exercising immediately and consult a professional", "tm.s5.h": "5. Limits of the service and disclaimer", "tm.s5.li1": "Every number, prediction and coaching cue in Runvis is <b>information for reference</b> based on published sports-science formulas, and is not a medical diagnosis, treatment or prescription", "tm.s5.li2": "By the nature of the sensors, heart-rate, GPS and running-dynamics measurements can carry error, and their accuracy is not warranted", "tm.s5.li3": "The developer accepts no legal liability for the outcomes of training based on this reference information (changes in performance, injury and so on), except for damage caused by intent or gross negligence", "tm.s5.li4": "The service is provided “as is”, and individual features may change or stop working as the Apple platform or external APIs (weather and the like) change", "tm.s6.h": "6. Intellectual property", "tm.s6.p": "The design, wording and code of the app and the website belong to the developer. Your workout and health data is entirely yours.", "tm.s7.h": "7. Changes to these terms", "tm.s7.p": "When these terms change, the effective date on this page is updated, and significant changes are announced inside the app.", "tm.s8.h": "8. Contact", "tm.s8.p": "<a href=\"mailto:help@runvis.app\">help@runvis.app</a> · For how your data is handled, see the <a href=\"privacy.html\">Privacy Policy</a>.", "tm.updated": "Effective: 6 September 2026 · version 1.2", "vchip0": "25 seconds under target pace", "vchip1": "In 300 meters: a climb of 800 meters, averaging 4 percent. Shorten your stride, keep the rhythm.", "vchip2": "Cadence is 5 percent under your baseline — let’s shorten the stride a touch.", "vchip3": "Heart rate is down to zone 3. You’re recovering well — almost there.", "n.why.cost": "There is no extra device to buy. The Apple Watch already on your wrist is the hardware. The only cost is the coach: ₩1,900 a month, ₩15,000 a year, or ₩39,000 once for the lifetime pass, at Korean App Store prices. You need one watch per person; the lifetime pass is a single ₩39,000 payment and covers an Apple Family Sharing group. What a dedicated watch does differently is <a href=\"how-it-works.html#versus\">written out metric by metric</a>.", "n.live.q.sum": "Up to 8 cues per 30 minutes on an easy run, 6 on a tempo or a race, and never two inside 45 seconds. Splits sit outside both rules and always come; hill warnings sit outside the 30-minute budget but still wait 45 seconds after the last cue. On intervals the switches you left on set the frequency instead of a ceiling.", "pl.month": "Monthly", "pl.year": "Yearly", "pl.life": "Lifetime", "pr.year": "₩15,000", "pr.life": "₩39,000", "pr.monthn": "Renews monthly · cancel any time", "pr.yearn": "About ₩1,250 a month · roughly 34% less than monthly", "pr.lifen": "One purchase · no auto-renewal · Apple Family Sharing", "n.price.moreh": "Prices in other regions, the real saving, the break-even sum", "n.price.nowh": "On from the moment you subscribe", "n.price.laterh": "Fills in as your runs add up", "n.price.f6": "The post-run tip card", "n.beta.order": "There is no opening date yet. Invitations go out in the order they were requested, and Apple caps TestFlight external testers at 10,000 seats. Leaving an address now is what fixes your place inside those 10,000.", "hz.h": "Something to work out right now — your five heart-rate zones", "hz.p": "The same Karvonen arithmetic Runvis speaks from. In the app the inputs keep refreshing — a seven-day resting heart rate from Apple Health, and the highest heart rate your watch has actually recorded — but the calculation is the one below.", "hz.age": "Age", "hz.rest": "Resting heart rate", "hz.max": "Max heart rate (leave empty if unknown)", "hz.bpm": "bpm", "hz.note": "Zone floor = (max HR − resting HR) × 50/60/70/80/90% + resting HR. With the maximum left empty it is estimated as 208 − 0.7 × age. Reference arithmetic, not medical advice.", "hz.bad": "The resting rate is too close to the maximum to split into zones.", "hz.z1": "Z1 Recovery", "hz.z2": "Z2 Aerobic", "hz.z3": "Z3 Tempo", "hz.z4": "Z4 VO2max", "hz.z5": "Z5 Anaerobic", "hz.maxtyped": "Using the maximum you entered", "hz.maxest": "Maximum estimated as 208 − 0.7 × age", "form.okaddr": "Address received", "r.cue": "SCROLL TO START ▾", "n.today.mininote": "These three cells are example values that show how the screen is laid out. The capture beside them is the real app.", "pr.approx2": "Those conversions are there to give the amounts a size; they are not what you would be charged. Apple charges by price point, and each country’s price points are set separately, so the real figure sits at a round local price above or below them. The real numbers go on this page as each store is set up. The app’s purchase screen never guesses — it prints the price the store hands it.", "hw.meta.title": "Rules and tools — Runvis", "hw.meta.desc": "Metric by metric, the formulas Runvis uses for training load, recovery time and an estimated lactate threshold without a dedicated running watch. Plus the full speaking rules, a heart-rate zone calculator, 13 Seoul course GPX files, and how the beta runs.", "hw.h1": "Rules and tools", "hw.intro": "The full version of what the home page states in one line each. Nothing here needs an e-mail address or an install.", "hw.s1.h": "Every ceiling and every exception", "hw.vs.h": "Garmin Forerunner, Coros: what is the same and what is different", "hw.vs.p": "Training load, recovery time, an estimated lactate threshold, a race pace plan — the numbers people are told they need a running watch like a Garmin Forerunner or a Coros to see. Companies already do this inside their own hardware; what nobody was doing was doing it on an Apple Watch. Runvis computes the same numbers from the heart rate, GPS and barometric altitude your Apple Watch already recorded. A dedicated watch does not publish its formulas, so we will not claim they are the same ones. What we will do is name ours: every formula below is a published, named one. Inside the app each metric opens onto what it means, how it was computed and your own usual range.", "hw.vs.th1": "Metric", "hw.vs.th2": "What Runvis computes it with, and what that formula is called", "hw.vs.r1a": "Training load and form (TSB)", "hw.vs.r1b": "Banister TRIMP fed into Coggan’s 42-day and 7-day exponential moving averages (CTL and ATL); the difference between them is TSB.", "hw.vs.r2a": "Recovery time", "hw.vs.r2b": "Estimated from three things: the last run’s TRIMP, your current TSB and your HRV status. The screen says “estimated” too.", "hw.vs.r3a": "Lactate Threshold (est.)", "hw.vs.r3b": "The pace and heart rate of your best 30-minute (or 20-minute) stretch held above 85% of maximum heart rate in the last 90 days. An estimate read off your runs, not a lab blood draw.", "hw.vs.r4a": "Race prediction and segment pace plan", "hw.vs.r4b": "Riegel extrapolation plus Runvis VDOT. Give it a course GPX and it splits the pace segment by segment along that course’s elevation.", "hw.vs.r5a": "Grade-adjusted pace (GAP)", "hw.vs.r5b": "Minetti’s (2002) running energy-cost curve, with the cost of climbing and descending worked out separately.", "hw.vs.r6a": "The five heart-rate zones", "hw.vs.r6b": "Karvonen, over heart-rate reserve; with no known maximum it falls back to 208 − 0.7 × age. The calculator below is the same arithmetic.", "hw.vs.note": "What a dedicated watch does and Runvis does not, written down too: there is no watch-face complication, no iPhone home-screen widget and no Live Activity in this version. And every number above is reference information, not medical advice."};
if(window.RunvisOnDict)window.RunvisOnDict("en");
